window.ScripturaLexicons.BDAG_PART_0370 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0370-01\" data-source=\"BDAG\" data-search=\"ὑπήνεγκα remissão v. ὑποφέρω. BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπήνεγκα</td><td>remissão</td><td>v. ὑποφέρω.</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0370-02\" data-source=\"BDAG\" data-search=\"ὑπηρεσία, ας, ἡ substantivo feminino serviço BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπηρεσία, ας, ἡ</td><td>substantivo feminino</td><td>serviço</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0370-03\" data-source=\"BDAG\" data-search=\"ὑπηρετέω verbo servir; prestar serviço; ser útil BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπηρετέω</td><td>verbo</td><td>servir; prestar serviço; ser útil</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0370-04\" data-source=\"BDAG\" data-search=\"ὑπηρέτης, ου, ὁ substantivo masculino auxiliar; assistente; servidor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπηρέτης, ου, ὁ</td><td>substantivo masculino</td><td>auxiliar; assistente; servidor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0370-05\" data-source=\"BDAG\" data-search=\"ὑπισχνέομαι verbo prometer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπισχνέομαι</td><td>verbo</td><td>prometer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0370-06\" data-source=\"BDAG\" data-search=\"ὕπνος, ου, ὁ substantivo masculino sono BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὕπνος, ου, ὁ</td><td>substantivo masculino</td><td>sono</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0370-07\" data-source=\"BDAG\" data-search=\"ὑπνόω verbo dormir; adormecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπνόω</td><td>verbo</td><td>dormir; adormecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0370-08\" data-source=\"BDAG\" data-search=\"ὑπό preposição por; sob; abaixo de; por volta de BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπό</td><td>preposição</td><td>por; sob; abaixo de; por volta de</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0370-09\" data-source=\"BDAG\" data-search=\"ὑποβάλλω verbo instigar; subornar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑποβάλλω</td><td>verbo</td><td>instigar; subornar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0370-10\" data-source=\"BDAG\" data-search=\"ὑπογραμμός, οῦ, ὁ substantivo masculino modelo; exemplo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπογραμμός, οῦ, ὁ</td><td>substantivo masculino</td><td>modelo; exemplo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0370-11\" data-source=\"BDAG\" data-search=\"ὑποδεής, ές adjetivo inferior; subordinado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑποδεής, ές</td><td>adjetivo</td><td>inferior; subordinado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0370-12\" data-source=\"BDAG\" data-search=\"ὑπόδειγμα, ατος, τό substantivo neutro exemplo; modelo; esboço; símbolo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπόδειγμα, ατος, τό</td><td>substantivo neutro</td><td>exemplo; modelo; esboço; símbolo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0370-13\" data-source=\"BDAG\" data-search=\"ὑποδείκνυμι ou ύω verbo indicar; mostrar; instruir; advertir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑποδείκνυμι ou ύω</td><td>verbo</td><td>indicar; mostrar; instruir; advertir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0370-14\" data-source=\"BDAG\" data-search=\"ὑποδέχομαι verbo acolher; receber hospitaleiramente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑποδέχομαι</td><td>verbo</td><td>acolher; receber hospitaleiramente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0370-15\" data-source=\"BDAG\" data-search=\"ὑποδέω verbo atar por baixo; calçar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑποδέω</td><td>verbo</td><td>atar por baixo; calçar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0370-16\" data-source=\"BDAG\" data-search=\"ὑπόδημα, ατος, τό substantivo neutro sandália; calçado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπόδημα, ατος, τό</td><td>substantivo neutro</td><td>sandália; calçado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0370-17\" data-source=\"BDAG\" data-search=\"ὑπόδικος, ον adjetivo sujeito a julgamento; responsável BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπόδικος, ον</td><td>adjetivo</td><td>sujeito a julgamento; responsável</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0370-18\" data-source=\"BDAG\" data-search=\"ὑπόδουλος, ον adjetivo escravizado; submetido como escravo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπόδουλος, ον</td><td>adjetivo</td><td>escravizado; submetido como escravo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0370-19\" data-source=\"BDAG\" data-search=\"ὑποδραμών remissão v. ὑποτρέχω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑποδραμών</td><td>remissão</td><td>v. ὑποτρέχω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0370-20\" data-source=\"BDAG\" data-search=\"ὑποδύομαι verbo colocar-se debaixo; tomar posição sob BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑποδύομαι</td><td>verbo</td><td>colocar-se debaixo; tomar posição sob</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0370-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπήνεγκα</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπήνεγκα</span> v. <span class=\"greek\">ὑποφέρω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0370-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπηρεσία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπηρεσία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (de <span class=\"greek\">ὑπηρέτης</span>, cf. <span class=\"greek\">ὑπηρετέω</span>; orig. um ‘corpo de remadores, tripulação de navio’, depois ‘serviço’ em geral: Thu., Aristoph.+; Ael. Aristid. 28, 81 K.=49 p. 518 D.: <span class=\"greek\">ἡ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">ὑπ</span>.; Epict. 3, 24, 114: a Deus; inscr., papiros, LXX; TestJob 10:7; 15:1; ViDa 1 [p. 76, 13 Sch.]; SJCh 107, 7; Philo; Jos., Ant. 16, 184; Just., D. 131, 2; Tat. 17:3) serviço de Moisés ao trazer juízo sobre o Egito 1 Cl 17:5; em sátira: de utensílios de barro usados <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀτιμοτάτην</span> <span class=\"greek\">ὑπηρεσίαν</span> para o serviço mais humilde Dg 2:2.—DELG s.v. <span class=\"greek\">ὑπηρέτης</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0370-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπηρετέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπηρετέω</span> fut. 3 sg. <span class=\"greek\">ὑπηρετήσει</span> Sir 39:4; aor. <span class=\"greek\">ὑπηρέτησα</span> (cf. <span class=\"greek\">ὑπηρεσία</span>; Trag., Hdt.+; inscr., papiros, Wsd; Sir 39:4; TestAbr, TestJob; TestJos 14:3; JosAs 17:4; EpArist, Philo, Joseph., Just., Tat.; Ath. 37, 2) prestar serviço, servir, ser útil com dat. de pessoa (Hyperid. 3, 39; PSI 502, 30 [257 a.C.]; JosAs 17:4; Just., A I, 17, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:23</a>; Hm 8:10; Hs 9, 10, 2. <span class=\"greek\">Δαυὶδ</span> <span class=\"greek\">ὑπηρετήσας</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">βουλῇ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:36</a> (Just., D, 125, 3; de obediência a Deus Aristaen., Ep. 1, 17 p. 148 H. <span class=\"greek\">ὑπ</span>. <span class=\"greek\">θεῷ</span>).—B 1:5. <span class=\"greek\">ἐν</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ὑπηρετεῖ</span> <span class=\"greek\">μοι</span> ele me presta serviço na palavra de Deus IPhld 11:1. <span class=\"greek\">ὑπ</span>. <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> oferecer algo (a título de auxílio) a alguém (Epict. 4, 1, 37; Polyaenus 7, 23, 2; Lucian, Tim. 22; Jos., Ant. 14, 99) Dg 11:1. Com dat. de coisa (PRev 22, 1 [258 a.C.]) <span class=\"greek\">ταῖς</span> <span class=\"greek\">χρείαις</span> <span class=\"greek\">μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:34</a> (cf. Jos., Ant. 13, 225; TestJob 11:1 <span class=\"greek\">τῇ</span> <span class=\"greek\">διακονία</span>; Just., D. 42, 3; Tat. 17, 3; sobre o motivo v. JLambrecht, Paul’s Farewell-Address at Miletus [Acts 20: 17–38]: Les Actes des Apôtres, ed. JKremer ’78, 321 e 336). V. <span class=\"greek\">ὑπηρέτης</span>.—DELG s.v. <span class=\"greek\">ὑπηρέτης</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0370-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπηρέτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπηρέτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Aeschyl., Hdt.+; inscr., papiros, LXX; TestBenj 3:8; EpArist, Philo, Joseph., Just.; Tat. 4, 2; empréstimo na literatura rabínica; freq. como termo técnico para funcionário governamental ou de outra natureza) aquele que exerce a função de auxiliar, freq. em posição subordinada, auxiliar, assistente (p. ex., assistente de médico: Hobart 88f; como ajudante de ordens: Arrian, Tact. 10, 4; 14, 4; o lictor ao lado do cônsul: Appian, Liby. 90 §424; os 20 senadores com Pompeu: Appian, Bell. Civ. 2, 18 §67; os auxiliares do sacerdote: Diod S 1, 73, 3; o assistente do <span class=\"greek\">ἡγούμενος</span> de uma associação cultual: Sb 7835, 11 [I a.C.]) Dg 7:2. João (Marcos) como <span class=\"greek\">ὑπ</span>. de Paulo e Barnabé <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:5</a> (BHolmes, Luke’s Description of John Mark: JBL 54, ’35, 63–72; WHadorn, D. Gefährten u. Mitarbeiter des Pls: ASchlatter Festschr. 1922, 65–82; RTaylor, ET 54, ’42/43, 136–38). Dos servidores de um conselho ou tribunal (Diod S 14, 5, 1f e Appian, Bell. Civ. 1, 31 §138 dos servidores do tribunal; Diod S 17, 30, 4 <span class=\"greek\">παρέδωκε</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὑπηρέταις</span> … <span class=\"greek\">ἀποκτεῖναι</span>; Maximus Tyr. 3, 2b), do Sinédrio (Jos., Bell. 1, 655 <span class=\"greek\">παρέδωκεν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὑπ</span>. <span class=\"greek\">ἀνελεῖν</span>, Ant. 4, 37 <span class=\"greek\">πέμψας</span> <span class=\"greek\">ὑπ</span>.; 16, 232) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:25</a> (Ael. Aristid. 45 p. 68 D.: <span class=\"greek\">ὁ</span> <span class=\"greek\">δικαστὴς</span> <span class=\"greek\">παραδίδωσι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὑπηρέταις</span> ‘oficiais subalternos’); 26:58; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.54\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:54</a>, 65; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:32</a>, 45f; 18:3, 12, 22; 19:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:22</a>, 26; GJs 10:1; 15:2. Com <span class=\"greek\">δοῦλοι</span> (como Pla., Polit. 289c [sobre isso Collins 81–84, v. abaixo]; Just., A I, 14, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:18</a>. De um servidor de sinagoga (como prov. na inscrição sepulcral romano-judaica: RGarrucci, Dissertazioni archeologiche II 1865, p. 166 n.º 22) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:20</a> (<span class=\"greek\">ὑπ</span>. como título de funcionários cultuais: Thieme 33. Também Musaeus, Fgm. 11 Diels [Paus. 10, 5, 6]: Pírcon como <span class=\"greek\">ὑπηρέτης</span> <span class=\"greek\">ἐς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μαντεύματα</span> de Posêidon; Dio Chrys. 19 [36], 33 <span class=\"greek\">ὑπ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">τελετῶν</span>; PLond 2710 recto, 11 [HTR 29, ’36, p. 40; 50]). Do séquito de um rei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:36</a>; GJs 21:2; 23:1f. Os apóstolos como auxiliares de Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:16</a>; 1 Cor 4:1 (Epict. 3, 22, 82 o cínico como <span class=\"greek\">ὑπ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Διός</span>; Galen, Protr. 5 p. 12, 5 J.: Sócrates, Hom. et al. como <span class=\"greek\">ὑπ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; dito pitagórico: WienerStud 8, 1886, p. 278 n.º 105 <span class=\"greek\">τὸν</span> <span class=\"greek\">εὐεργετοῦντά</span> <span class=\"greek\">σε</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ὑπηρέτην</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">τίμα</span>=aquele que te beneficiou espiritualmente, estima-o como auxiliar de Deus, depois de Deus; Sextus 319; Just., D. 57, 3). Os crentes em geral como <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ὑπηρέται</span> (com <span class=\"greek\">οἰκονόμοι</span> [como 1 Cor 4:1] e <span class=\"greek\">πάρεδροι</span>) IPol 6:1 (cf. PGM 59, 3; 5 e Jos., Bell. 2, 321, Ant. 3, 16).—Também com gen. objetivo daquilo a que se prestam serviços (Appian, Bell. Civ. 3, 41 §169 <span class=\"greek\">τῆς</span> <span class=\"greek\">πατρίδος</span> <span class=\"greek\">ὑπ</span>.; Wsd 6:4) <span class=\"greek\">ὑπηρέται</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λόγου</span> ministros da palavra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:2</a> (cf. o papel de um escriba Sir 39:1–4; PMather, BR 30, ’85, 28f). <span class=\"greek\">ἐκκλησίας</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ὑπηρέται</span> servidores da assembleia/igreja de Deus ITr 2:3.—Sobre a obscura expressão <span class=\"greek\">οἱ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐχθρῶν</span> <span class=\"greek\">ὑπηρέται</span> B 16:4 v. Windisch, Hdb. ad loc.—Sobre as funções do <span class=\"greek\">ὑπ</span>. no Egito greco-romano, HKupiszewski e JModrzejewski, JJP XI e XII, ’57/58, 141–66; JCollins, Diakonia ’90, esp. 81–84, 173–75.—B. 1334. DELG. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0370-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπισχνέομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπισχνέομαι</span> (cf. a forma colateral <span class=\"greek\">ὑπέχομαι</span>, v. L-S-J-M s.v. <span class=\"greek\">ὑπισχνέομαι</span>) depoente médio (Hom.+; inscr., papiros, LXX; ApcSed 16 p. 137, 8 Ja. [<span class=\"greek\">ὑπόσχομαι</span>]; Philo; Jos., Ant. 11, 228, Vi. 111; SibOr 3, 769) 2 aor. <span class=\"greek\">ὑπεσχόμην</span> prometer com dat., seguido do inf. aor. Pol 5:2.—B. 1272. DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0370-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕπνος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὕπνος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom.+) sono lit. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:24</a>; GJs 14:2 (uma ordem divina durante o sono, como p. ex. ChronLind D, 68f; Diod S 1, 53, 9 Hefesto <span class=\"greek\">κατ</span>’ <span class=\"greek\">ὕπνον</span>; 5, 51, 4); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:13</a>; <span class=\"greek\">καταφερόμενος</span> <span class=\"greek\">ὕπνῳ</span> <span class=\"greek\">βαθεῖ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:9a</a> (Longus 1, 22, 3; =sopor altus Vergil, Aeneid 8, 27); cf. 9b; semelhantemente AcPl Ha 3, 26. Também em sentido figurado (freq. Philo) <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὕπνου</span> <span class=\"greek\">ἐγερθῆναι</span> despertar do sono, i.e., despedir-se das obras das trevas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:11</a> (quanto a <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὕπνου</span> cf. Appian, Liby. 21 §88).—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0370-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπνόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπνόω</span> fut. <span class=\"greek\">ὑπνώσω</span> LXX; 1 aor. <span class=\"greek\">ὕπνωσα</span> intr. dormir, adormecer (<span class=\"greek\">ὕπνος</span>; Hippocr., Polyb. et al.; BGU 1141, 35 [14 a.C.]; LXX; En 100, 5; Test12Patr; JosAs 10:2; ParJer 5:2; Philo; Jos., Ant. 1, 208; Ath., R. 16 p. 68, 5 e 10) 1 Cl 26:2 (Ps 3:6).—DELG s.v. <span class=\"greek\">ὕπνος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0370-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπό</h1><div class=\"entry-meta\"><span>preposição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπό</span> (Hom.+; inscr., papiros, LXX, En, TestSol; TestAbr A; TestAbr B 14 p. 148, 20 [Stone p. 84 gen.]; TestJob, Test12Patr, JosAs, ParJer, GrBar [gen.], ApcEsdr [gen.], ApcSed [gen.], ApcMos [gen.], AscIs [gen.], EpArist, Philo, Joseph.; apologistas [em Ath. somente gen.]) prep. com gen. e acus., em nossa literatura não com dat. (v. B-D-F §203; Rob. 634; quanto ao uso v. B-D-F §232; Rob. 633–36; com dat. TestSol 13:6 C; Just., D. 126, 5; 132, 2).—Bibliografia s.v. <span class=\"greek\">ἀνά</span>, início.</p><p class=\"entry-text\">A. Com gen. marcador de agente ou causa, por (em nossa literatura, assim como na LXX, já não em sentido local)</p><p class=\"entry-text\">ⓐ Com a voz passiva de um verbo</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Com gen. de pessoa <span class=\"greek\">τὸ</span> <span class=\"greek\">ῥηθὲν</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">κυρίου</span> (cf. Gen 45:27; SIG 679, 85; Just., D. 44, 1 <span class=\"greek\">εἰρῆσθαι</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; <span class=\"greek\">τὰ</span> <span class=\"greek\">εἰρημένα</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προφητῶν</span>) Mt 1:22 (Jos., Ant. 8, 223 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">προφήτου</span>; Just., A I, 5, 4 <span class=\"greek\">διὰ</span> <span class=\"greek\">Σωκράτους</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">λόγου</span>); 2:15. Cf. v. 16; Mk 1:13; Lk 2:18; J 14:21; Ac 4:11; 1 Cor 1:11; 2 Cor 1:4; Gal 1:11; Eph 2:11; Phil 3:12; 1 Th 1:4; 1 Cl 12:2; 2 Cl 1:2; Hm 4, 3, 6 e freq.; AcPlCor 2:7. Também com a passiva no sentido de ‘deixar-se … por’ Mt 3:6, 13; Mk 1:5, 9.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Com gen. de coisa (cf. X., An. 1, 5, 5 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">λιμοῦ</span> <span class=\"greek\">ἀπολέσθαι</span>; Diod S 5, 54, 3 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">σεισμῶν</span> <span class=\"greek\">διεφθάρησαν</span>; Nicol. Dam.: 90 Fgm. 22 p. 342, 17 Jac. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">φαρμακῶν</span> <span class=\"greek\">διαφθαρείς</span>; Appian, Liby. 35 §147 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">χειμῶνος</span> <span class=\"greek\">κατήγοντο</span>, Bell. Civ. 4, 123 §515; Longus 2, 18 um nariz esmagado <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">πληγῆς</span> <span class=\"greek\">τινος</span>; Herm. Wr. 10, 4b; Tat. 8, 5 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">βραχείας</span> <span class=\"greek\">αὔρας</span> <span class=\"greek\">νικηθείς</span>; UPZ 42, 9 [162 a.C.]) <span class=\"greek\">καλύπτεσθαι</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κυμάτων</span> Mt 8:24. Cf. 11:7; 14:24; Lk 7:24; 8:14; Ac 27:41; Ro 3:21; 12:21; 1 Cor 10:29; 2 Cor 5:4; Col 2:18; Js 1:14; 3:4ab; 2 Pt 2:17; Jd 12; Rv 6:13; Hm 10, 1, 4.</p><p class=\"entry-text\">ⓑ Com verbos e expressões verbais que têm sentido passivo <span class=\"greek\">πάσχειν</span> <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span> (Mel., P. 75, 546ff; v. <span class=\"greek\">πάσχω</span> 3a<span class=\"greek\">β</span>; 3b) Mt 17:12; Mk 5:26; 1 Th 2:14ab. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">χειρὸς</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">παθεῖν</span> B 5:5 (cf. Mel., P. 96, 737 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">δεξιᾶς</span> <span class=\"greek\">Ἰσραηλίτιδος</span>). <span class=\"greek\">ἀπολέσθαι</span> 1 Cor 10:9f (Jos., Ant. 2, 300; cf. Sb 1209 <span class=\"greek\">Ἀπολλώνιος</span> <span class=\"greek\">ἐτελεύτησεν</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">σκορπίου</span>). <span class=\"greek\">ὑπομένειν</span> <span class=\"greek\">ἀντιλογίαν</span> Hb 12:3. <span class=\"greek\">τεσσεράκοντα</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">μίαν</span> <span class=\"greek\">λαβεῖν</span> 2 Cor 11:24. <span class=\"greek\">ἃ</span> … <span class=\"greek\">παρέλαβον</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῶν</span> … <span class=\"greek\">ἀποστόλων</span> o que recebi dos apóstolos AcPlCor 2:2; <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἀναστάς</span> ressuscitado por Deus Pol 9:2. <span class=\"greek\">γίνεσθαι</span> <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span> ser feito por alguém (v. <span class=\"greek\">γίνομαι</span> 2a) Lk 13:17; 23:8; Ac 20:3; 26:6; Eph 5:12. Cf. Ac 23:30 v.l. O texto de GJs 18:3 (não o papiro) é suspeito. Com <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">γυναικός</span> Hv 1, 2, 3 deve-se suprir algo como ‘foi ocasionado’.</p><p class=\"entry-text\">ⓒ Com substantivos <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπιτιμία</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πλειόνων</span> a punição imposta pela maioria 2 Cor 2:6 (cf. X., Cyr. 3, 3, 2 <span class=\"greek\">ἡ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">τιμή</span>; SIG 1157, 10 <span class=\"greek\">διὰ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">εὐεργεσίας</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; Esth 1:20 <span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βασιλέως</span>).</p><p class=\"entry-text\">ⓓ Quando empregado com uma forma ativa, <span class=\"greek\">ὑπό</span> introduz aquele por cuja intervenção se torna possível a ação expressa pelo verbo (Hdt. 9, 98; Pla., Phlb. 66a <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">ἀγγέλων</span> <span class=\"greek\">φράζειν</span>=‘dizer por intermédio de mensageiros’; cf. Herm. Wr. 9, 9 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">δεισιδαιμονίας</span> <span class=\"greek\">βλασφημεῖν</span>; Just., D. 2, 6 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">βλακείας</span> <span class=\"greek\">ἤλπιζον</span> <span class=\"greek\">αὐτίκα</span> <span class=\"greek\">κατόψεσθαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>=em minha estupidez pensei que imediatamente contemplaria Deus) <span class=\"greek\">ἀποκτεῖναι</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θηρίων</span> Rv 6:8. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ἀγγέλου</span> <span class=\"greek\">βλέπεις</span> vês sob a orientação de um anjo Hs 9, 1, 2b; cf. ibid. 2a e v. Mayser II/2, 511f; à ref. ali indicada acrescente-se PLeid XI, 1, col. 1, 15.</p><p class=\"entry-text\">B. Com acus.</p><p class=\"entry-text\">① Posição abaixo de um objeto ou de outra posição, sob, com acus. de lugar sob, abaixo de</p><p class=\"entry-text\">ⓐ Respondendo à pergunta ‘para onde?’ <span class=\"greek\">ἔρχεσθαι</span> 1 Cl 16:17; Hs 8, 1, 1 (PsSol 18:7). <span class=\"greek\">εἰσέρχεσθαι</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">στέγην</span> Mt 8:8 (cf. Ar. 15, 7 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">στέγην</span> <span class=\"greek\">εἰσάγουσιν</span>); Lk 7:6. <span class=\"greek\">συνάγειν</span> 1 Cl 12:6. <span class=\"greek\">ἐπισυνάγειν</span> Mt 23:37; Lk 13:34. <span class=\"greek\">τιθέναι</span> Mt 5:15; Mk 4:21ab; Lk 11:33. <span class=\"greek\">κρύπτειν</span> (cf. Job 20:12) 1 Cl 12:3. Também (abaixo) em <span class=\"greek\">κάθου</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὑποπόδιόν</span> <span class=\"greek\">μου</span> Js 2:3 (cf. ParJer 5:1 <span class=\"greek\">ἐκάθισεν</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σκίαν</span>; Just., D. 107, 3). <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> sob os pés (Hdt. 7, 88, 1) 1 Cor 15:25, 27; Eph 1:22. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">συντρίψει</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">σατανᾶν</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">ὑμῶν</span> Deus esmagará Satanás de modo que ele jazerá aos vossos pés Ro 16:20.</p><p class=\"entry-text\">ⓑ Em resposta à pergunta ‘onde?’ (Il. 5, 267; Ael. Aristid. 39 p. 734 D.: <span class=\"greek\">τὰ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἥλιον</span>; Maximus Tyr. 35, 5b) Mk 4:32. <span class=\"greek\">ὄντα</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">συκῆν</span> J 1:48. Cf. Ro 3:13 (Ps 13:3; 139:4); 1 Cor 10:1; Jd 6. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρανόν</span> sob o céu=na terra Ac 4:12; como adj. <span class=\"greek\">ὁ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρανόν</span> (que se encontra) sob o céu=na terra (Demosth. 18, 270; UPZ 106, 14 [99 a.C.] <span class=\"greek\">τῶν</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρανὸν</span> <span class=\"greek\">χωρῶν</span>; Just., A II, 5, 2; cf. sem o art. PsSol 2:32; TestAbr A 15 p. 96, 5 [Stone p. 40]) 2:5; Col 1:23; Hm 12, 4, 2; <span class=\"greek\">ἡ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρανόν</span> (deve-se suprir <span class=\"greek\">χώρα</span>; cf. Ex 17:14; Job 28:24) Lk 17:24a; cf. b. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ζυγὸν</span> <span class=\"greek\">δοῦλοι</span> (<span class=\"greek\">ζυγός</span> 1) 1 Ti 6:1.</p><p class=\"entry-text\">② Marcador daquilo que ocupa uma posição de domínio, sob, sob o controle de, sob obrigação, em ref. a poder, governo, soberania, comando etc., com acus. (OGI 56, 13 [237 a.C.] <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">βασιλείαν</span> <span class=\"greek\">τασσόμενοι</span>; PHib 44 [253 a.C.] et al. nos papiros; Just., D. 52, 4 <span class=\"greek\">εἶναι</span> … <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ἴδιον</span> <span class=\"greek\">βασιλέα</span>) <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ἐξουσίαν</span> <span class=\"greek\">τασσόμενος</span> (<span class=\"greek\">ἐξουσία</span> 4) Lk 7:8a; cf. Mt 8:9a; Hs 1:3 (Vett. Val. 209, 35 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ἑτέρων</span> <span class=\"greek\">ἐξουσίαν</span> <span class=\"greek\">ὄντας</span>). <span class=\"greek\">ἔχων</span> <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">ἐμαυτὸν</span> <span class=\"greek\">στρατιώτας</span> (Polyb. 4, 87, 9 <span class=\"greek\">Μεγαλέαν</span> <span class=\"greek\">ὑφ</span>’ <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">εἶχεν</span>) Mt 8:9b; Lk 7:8b (OGI 86, 11 [III a.C.] <span class=\"greek\">οἱ</span> <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">τεταγμένοι</span> <span class=\"greek\">στρατιῶται</span>). <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινα</span> <span class=\"greek\">εἶναι</span> estar sob o poder de alguém (Thu. 6, 86, 4; PSI 417, 36 [III a.C.] <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὅρκον</span> <span class=\"greek\">εἶναι</span>) Gal 3:25; 4:2; <span class=\"greek\">ὑφ</span>’ <span class=\"greek\">ἁμαρτίαν</span> Ro 3:9; <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">νόμον</span> 6:14, 15 (ambos em oposição a <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">χάριν</span>); 1 Cor 9:20abcd; Gal 4:21; 5:18; <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">κατάραν</span> 3:10. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">νόμον</span> <span class=\"greek\">ἐφρουρούμεθα</span> v. 23. <span class=\"greek\">γενόμενος</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">νόμον</span> Gal 4:4 (<span class=\"greek\">γινομαι</span> 9d e Thu. 1, 110, 2 <span class=\"greek\">Αἴγυπτος</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">βασιλέα</span> <span class=\"greek\">ἐγένετο</span>). <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">στοιχεῖα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">ἤμεθα</span> <span class=\"greek\">δεδουλωμένοι</span> v. 3. <span class=\"greek\">συνέκλεισεν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">γραφὴ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ἁμαρτίαν</span> 3:22 (v. <span class=\"greek\">συγκλείω</span> 2). <span class=\"greek\">πεπραμένος</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἁμαρτίαν</span> Ro 7:14. <span class=\"greek\">ταπεινώθητε</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">χεῖρα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> 1 Pt 5:6 (v. <span class=\"greek\">ταπεινόω</span> 3); cf. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔκλινας</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κεφαλήν</span> <span class=\"greek\">σου</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κραταιὰν</span> <span class=\"greek\">χεῖραν</span> GJs 15:4; <span class=\"greek\">τὸ</span> <span class=\"greek\">αἷμά</span> <span class=\"greek\">σου</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">χεῖράν</span> <span class=\"greek\">μού</span> <span class=\"greek\">ἐστιν</span> 23:2. <span class=\"greek\">οἱ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">νόμον</span> aqueles que estão sob (o poder da, a obrigação para com a) lei Gal 4:5 (Just., D. 45, 3 [com art.]; cf. X., Cyr. 3, 3, 6 <span class=\"greek\">τινὰς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὑφ</span>’ <span class=\"greek\">ἑαυτούς</span>).</p><p class=\"entry-text\">③ Marcador do tempo aproximado de um período, por volta de, com acus. (com graus variáveis de precisão: no grego anterior: Aristoph et al.; PTebt 50, 18 [112 a.C.]; Jos., Ant. 14, 420. Raro na LXX e em nossa literatura) <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὄρθρον</span> por volta do romper do dia Ac 5:21 (v. <span class=\"greek\">ὄρθρος</span>).</p><p class=\"entry-text\">④ Usos especiais</p><p class=\"entry-text\">ⓐ <span class=\"greek\">ὑφ</span>’ <span class=\"greek\">ἕν</span> de uma só vez (Epict. 3, 22, 33; Wsd 12:9; Just., D. 65, 3 de assuntos tratados ‘coletivamente’) B 4:4. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">χεῖρα</span> continuamente (v. s.v. <span class=\"greek\">χείρ</span> 3) Hv 3, 10, 7; 5, 5; m 4, 3, 6.</p><p class=\"entry-text\">ⓑ <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἴχνη</span> IEph 12:2 é traduzido por nas pegadas. Pode <span class=\"greek\">ὑπό</span> significar isso, de modo semelhante a Ezk 13:8 (ed. JZiegler ’52 v.l.), onde corresponde a <span class=\"hebrew\" dir=\"rtl\">עַל</span>? Mas, se = ‘sob’, então <span class=\"greek\">τὰ</span> <span class=\"greek\">ἴχνη</span> exigiria interpretação diferente. V. <span class=\"greek\">ἴχνος</span> 2. V. os gramáticos: Kühner-Gerth II/1 521–26; Schwyzer II 522–23; Mayser II/2 509–15; Radermacher 114–19.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0370-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑποβάλλω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑποβάλλω</span> 2 aor. <span class=\"greek\">ὑπέβαλον</span> (Hom.+ em vários sentidos) instigar (secretamente), subornar (Da 3:9 Theod. v.l.; TestSim 3:3; Just., D. 49, 4 [com dat.]; Appian, Bell. Civ. 1, 74 §341 <span class=\"greek\">ὑπεβλήθησαν</span> <span class=\"greek\">κατήγοροι</span>;—<span class=\"greek\">ὑπόβλητος</span>=‘instigado secretamente’ Jos., Bell. 5, 439) <span class=\"greek\">τινά</span> alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:11</a>; MPol 17:2a. <span class=\"greek\">ταῦτα</span> <span class=\"greek\">ὑποβαλλόντων</span> <span class=\"greek\">Ἰουδαίων</span> (disseram) isso porque os judeus os instigaram 17:2b.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0370-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπογραμμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπογραμμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> lit. ‘modelo, padrão’ a ser copiado na escrita ou no desenho (2 Macc 2:28; cf. <span class=\"greek\">ὑπογράφειν</span> Pla., Protag. 326d; também Just.), depois, modelo de comportamento, exemplo (Ps.Clem., Hom. 4, 16; cf. Pla., Leg. 4, 711b <span class=\"greek\">πάντα</span> <span class=\"greek\">ὑπογράφειν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πράττειν</span>) de Paulo <span class=\"greek\">ὑπομονῆς</span> <span class=\"greek\">γενόμενος</span> <span class=\"greek\">μέγιστος</span> <span class=\"greek\">ὑπογραμμός</span> 1 Cl 5:7. Principalmente de Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:21</a>; 1 Cl 16:17; 33:8; <span class=\"greek\">τοῦτον</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὑπογραμμὸν</span> <span class=\"greek\">ἔθηκε</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">ἑαυτοῦ</span> Pol 8:2.—DELG s.v. <span class=\"greek\">γράφω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0370-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑποδεής, ές</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑποδεής</span>, <span class=\"greek\">ές</span> (<span class=\"greek\">δέομαι</span>)</p><p class=\"entry-text\">① Relativo a estar em posição inferior, inferior na literatura em geral (Hdt. et al., igualmente IG IV2/1, 91, 3 [III d.C.]; papiros, Joseph.) sempre no comp. <span class=\"greek\">ὑποδεέστερος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span>, pl. <span class=\"greek\">οἱ</span> <span class=\"greek\">ὑποδεέστεροι</span> ‘os que são inferiores’; assim também Dg 10:5.</p><p class=\"entry-text\">② Relativo a acatar a autoridade, submisso em sentido figurado, como subst. sing. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὑποδεές</span> <span class=\"greek\">τινος</span> a subordinação de alguém (com <span class=\"greek\">τὸ</span> <span class=\"greek\">ταπεινόφρον</span>) 1 Cl 19:1.—DELG s.v. <span class=\"greek\">ὑπό</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0370-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπόδειγμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπόδειγμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (v. <span class=\"greek\">ὑποδείκνυμι</span>; rejeitado pelos aticistas em favor de <span class=\"greek\">παράδειγμα</span> [Lob. sobre Phryn. p. 12]. Encontra-se em X., Equ. 2, 2, b e Philo Mech. 69, 10, depois a partir de Polyb. [exs. da literatura em FBleek, Hb II/1, 1836, 555]; Vett. Val.; IPriene 117, 57 [I a.C.]; OGI 383, 218; BGU 1141, 43 [I a.C.]; PFay 122, 16; LXX; EpArist 143; Philo, Joseph.)</p><p class=\"entry-text\">① Exemplo de comportamento empregado para fins de instrução moral, exemplo, modelo, padrão (escólio sobre Nicander, Ther. 382=exemplo; Polyb. 3, 17, 8; Sir 44:16) em sentido positivo, como algo que incita ou deveria incitar alguém a imitá-lo 1 Cl 5:1ab (<span class=\"greek\">τὰ</span> <span class=\"greek\">γενναῖα</span> <span class=\"greek\">ὑποδείγματα</span>); 6:1 (<span class=\"greek\">ὑπόδειγμα</span> <span class=\"greek\">κάλλιστον</span>.—Jos., Bell. 6, 103 <span class=\"greek\">καλὸν</span> <span class=\"greek\">ὑπόδειγμα</span>; Philo, Rer. Div. Her. 256); 46:1; 55:1; 63:1. <span class=\"greek\">ὑπόδειγμα</span> <span class=\"greek\">ἔδωκα</span> <span class=\"greek\">ὑμῖν</span> (cf. 2 Macc 6:28) J 13:15. Com gen. de coisa (Sir 44:16; 2 Macc 6:31) Js 5:10.—Em <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τις</span> <span class=\"greek\">ὑποδείγματι</span> <span class=\"greek\">πέσῃ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀπειθείας</span> Hb 4:11, <span class=\"greek\">ὑπόδειγμα</span> refere-se não a um exemplo de desobediência (como BGU 747 II, 13f [139 d.C.] <span class=\"greek\">ὑπόδιγμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀπειθίας</span>), mas a um exemplo de cair na destruição em consequência da desobediência.—Um exemplo de advertência (Cornutus 27 p. 51, 16; Vi. Aesopi W c. 95 <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὑπόδειγμα</span>=como exemplo de advertência; Jos., Bell. 2, 397) Sodoma e Gomorra são <span class=\"greek\">ὑπόδειγμα</span> <span class=\"greek\">μελλόντων</span> <span class=\"greek\">ἀσεβεῖν</span> para os ímpios do futuro 2 Pt 2:6 (<span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δεῖγμα</span> P72). De Judas <span class=\"greek\">μέγα</span> … <span class=\"greek\">ἀσεβείας</span> <span class=\"greek\">ὑπόδειγμα</span> um exemplo marcante de impiedade Papias (3:2).</p><p class=\"entry-text\">② Indicação de algo que aparece em tempo posterior, delineamento, esboço, símbolo <span class=\"greek\">ὑπόδειγμα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σκιά</span> Hb 8:5; 9:23 (Ezk 42:15; v. ELee, NTS 8, ’61/62, 167–69: ‘sugestão’; LHurst, JTS 34, ’83, 156–68).—PKatz, Biblica 33, ’52, 525.—DELG s.v. <span class=\"greek\">δείκνυμι</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0370-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑποδείκνυμι ou ύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑποδείκνυμι</span> ou <span class=\"greek\">ύω</span> fut. <span class=\"greek\">ὑποδείξω</span>; 1 aor. <span class=\"greek\">ὑπέδειξα</span>. Pass.: 1 fut. 3 sg. <span class=\"greek\">ὑποδειχθήσεται</span> Sir 14:12 v.l.; aor. 3 sg. <span class=\"greek\">ὑπεδείχθη</span> Sir 3:23; 14:12; perf. part. n. pl. <span class=\"greek\">ὑποδεδειγμένα</span> Esth 2:9 v.l. (Hdt., Thu.+) ‘mostrar, indicar’.</p><p class=\"entry-text\">① Dirigir a atenção de alguém para algo, indicar, apontar, lit. <span class=\"greek\">τινί</span> a alguém <span class=\"greek\">ὑποδεικνύουσα</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ἐναλλάξ</span> enquanto ela apontava na direção errada 1 Cl 12:4. Também de visões concedidas a mártires, aos quais o Senhor mostrou as bênçãos eternas que nenhum olho terreno pode contemplar, pass. MPol 2:3.</p><p class=\"entry-text\">② Dar instrução ou orientação moral, mostrar, orientar, provar, expor, extensão figurada de 1, <span class=\"greek\">τὶ</span> algo (TestJob 4:1; GrBar 1:8; Jos., Ant. 2, 21) B 1:8. Nos demais casos sempre com dat. de pessoa <span class=\"greek\">τινί</span> (a) alguém: seguido de oração relativa (TestJob 1:4; Ath., R. 23 p. 77, 8) Ac 9:16; seguido de inf. advertir Mt 3:7; Lk 3:7; seguido de <span class=\"greek\">ὅτι</span> (TestNapht 8:1; ApcMos 23; v. B-D-F §397, 4) Ac 20:35 (<span class=\"greek\">πάντα</span>=‘em toda oportunidade’); seguido de pergunta indireta (TestJob 3:2) Lk 6:47; 12:5.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0370-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑποδέχομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑποδέχομαι</span> depoente médio; fut. 3 pl. <span class=\"greek\">ὑποδέξονται</span> 4 Macc 13:17; 1 aor. <span class=\"greek\">ὑπεδεξάμην</span>; perf. <span class=\"greek\">ὑποδέδεγμαι</span> (Hom. et al.; inscr. [p. ex. IG X/2, 255, 5; 17], papiros, LXX; TestSol 16:2; TestAbr; Philo) receber hospitaleiramente, receber, acolher, hospedar como convidado <span class=\"greek\">τινά</span> alguém (POslo 55, 8 [c. 200 d.C.]; TestAbr 2 p. 78, 20 [Stone p. 4]; Jos., Ant. 1, 180 al.) Lk 10:38; 19:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:25</a>; ISm 10:1; AcPl Ant 13, 10 (=Aa I 237, 1). <span class=\"greek\">τινὰ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκίαν</span> (Chion, Ep. 2 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκίαν</span> <span class=\"greek\">ὑποδέχεσθαι</span> <span class=\"greek\">αὐτόν</span>) Lk 10:38 v.l. (v. <span class=\"greek\">οἰκία</span>; RBorger TRu 52, ’87, 32f); cf. Hs 8, 10, 3; 9, 27, 2 (<span class=\"greek\">ὑπ</span>. <span class=\"greek\">τινα</span> <span class=\"greek\">εἰς</span> como 1 Macc 16:15).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0370-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑποδέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑποδέω</span> (Aristot. et al.; 2 Ch 28:15) predominantemente médio em nossa literatura (aor. at. <span class=\"greek\">ὑπέδησα</span> somente LXX) e alhures: <span class=\"greek\">ὑποδέομαι</span> (assim Hdt., Aristoph. et al.) 1 aor. <span class=\"greek\">ὑπεδησάμην</span>; perf. part. <span class=\"greek\">ὑποδεδεμένος</span> atar/prender por baixo, calçar, de calçados (assim a média desde Alcaeus 21 Diehl2 [318 L-P.]); com acus. quer daquilo que se põe no pé (Hdt. et al.; <span class=\"greek\">ὑποδήματα</span> X., Mem. 1, 6, 6; Pla., Gorg. 490e; PGM 4, 934; 2123 <span class=\"greek\">σάνδαλα</span>; 7, 729 <span class=\"greek\">ὑποδήματα</span>) <span class=\"greek\">ὑπόδησαι</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">σανδάλιά</span> <span class=\"greek\">σου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:8</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:9</a>, quer de uma parte do corpo que é coberta (pé Thu. 3, 22, 2 <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀριστερὸν</span> <span class=\"greek\">πόδα</span> <span class=\"greek\">ὑποδεδεμένος</span>; Lucian, Hist. Conscrib. 22; Aelian, VH 1, 18) <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> calçar os pés <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:15</a>.—DELG s.v. 1 <span class=\"greek\">δέω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0370-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπόδημα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπόδημα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">ὑποδέω</span>; Hom.+; inscr., papiros, LXX; PsSol 2:2; TestZeb; Jos., Bell. 6, 85; Just.) sola de couro que é presa ao pé por meio de correias, sandália. Pl. (<span class=\"greek\">τὰ</span>) <span class=\"greek\">ὑποδήματα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:11</a>; 10:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:16</a>; 10:4; 15:22; 22:35; Hv 4, 2, 1 (sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:4</a> v. FSpitta, ZWT 55, 1913, 39–45; ibid. 166f; SKrauss, <span class=\"greek\">Αγγελος</span> I 1925, 96–102; JKleist, The Gospel of St. Mark ’36, 257f). O sing. como coletivo, calçado (TestZeb 3:4f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:27</a>. Com gen. <span class=\"greek\">τῶν</span> <span class=\"greek\">ποδῶν</span> (cf. Ps.-Pla., Alc. 1, 128a <span class=\"greek\">ποδός</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:25</a>. Em solo santo <span class=\"greek\">τὸ</span> <span class=\"greek\">ὑπόδημα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ποδῶν</span> deve ser retirado 7:33 (cf. Ex 3:5; Josh 5:15.—SIG 338, 25); v. JHeckenbach, De Nuditate Sacra 1911, 40ff; FPfister, ARW 9, 1906, 542; OWeinreich, Hessische Blätter für Volkskunde 10, 1911, 212f; Pauly-W. II 741–58; Kl. Pauly V 37f; BHHW III 1738.—B. 428. DELG s.v. 1 <span class=\"greek\">δέω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0370-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπόδικος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπόδικος</span>, <span class=\"greek\">ον</span> (Aeschyl.+; inscr., papiros, GrBar 4:9; Philo; Jos., Vi. 74; Ath., R. 18 p. 70, 27; 21 p. 74, 20) relativo a estar sujeito a julgamento/punição, passível de responder, responsável (Pla., Leg. 9, 871b et al.; inscr.; PFay 22, 9 [I a.C.] <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀδικουμένῳ</span>) <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:19</a>.—DELG s.v. <span class=\"greek\">δίκη</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0370-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπόδουλος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπόδουλος</span>, <span class=\"greek\">ον</span> (Physiogn. II 345, 15; SibOr 12, 130) escravizado, submetido como escravo <span class=\"greek\">γίνεσθαί</span> <span class=\"greek\">τινι</span> <span class=\"greek\">ὑπ</span>. tornar-se escravo de alguém (Ps.-Clem., Hom. 8, 20) Hm 12, 5, 4: visto que as vítimas do diabo começaram como ‘escravos’ de Deus, o Pastor contrapõe sua condição posterior mediante a forma intensiva <span class=\"greek\">ὑ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0370-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑποδραμών</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑποδραμών</span> v. <span class=\"greek\">ὑποτρέχω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0370-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑποδύομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑποδύομαι</span> 1 aor. part. pl. <span class=\"greek\">ὑποδύσαντες</span> Jdth 6:13; perf. <span class=\"greek\">ὑποδέδυκα</span>; mais-que-perf. <span class=\"greek\">ὑποδεδύκειν</span> (Hom. et al.; Jos., Ant. 15, 282 al.) colocar-se debaixo, tomar posição sob <span class=\"greek\">ὑπό</span> <span class=\"greek\">τι</span> (debaixo de) algo (Hdt. 1, 31): <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">γωνίας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λίθου</span> debaixo dos cantos da pedra Hs 9, 4, 1a. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πλευρῶν</span> ao longo dos lados ibid. b.—DELG s.v. <span class=\"greek\">δύω</span>.</p></section></article>"};